"""Copy the few trained weights the demo needs into weights/ (the rest are regenerated by the pipeline)."""
import os, shutil
SRC = {"cnn_full_s0.pt": "results/novelty/partB/full/cnn_full_lr0.001_do0.2_s0.pt",
       "hybrid_full_s0.pt": "results/novelty/partB/full/hybrid_full_lr0.0003_do0.2_s0.pt",
       "transformer_full_s0.pt": "results/novelty/partB/full/transformer_full_lr0.0003_do0.2_s0.pt",
       "multichem_heads_s0.pt": "results/novelty/partA/multi_heads_s0.pt",
       "single_U_s0.pt": "results/novelty/partA/single_U_s0.pt"}
os.makedirs("weights", exist_ok=True)
for dst, src in SRC.items():
    if os.path.exists(src):
        shutil.copy(src, f"weights/{dst}"); print("ok  ", dst, f"{os.path.getsize(src)/1e6:.1f} MB")
    else:
        print("MISS", src)

import json, sys, numpy as np, pandas as pd
sys.path[:0] = [".", "novelty"]
from data import build_chem_table, train_val
t = build_chem_table()
tr_idx = np.where(t.split.values == "train")[0]
f, _ = train_val(tr_idx, 0, 0.10)
y = t.rl_U.values[f]
json.dump({"mu": float(np.nanmean(y)), "sd": float(np.nanstd(y)), "note": "seed-0 fit-split statistics used at training time"},
          open("weights/scaler_s0.json", "w"), indent=1)
print("ok   scaler_s0.json", json.load(open("weights/scaler_s0.json")))

from bench import tertile_edges
tr = pd.read_csv("data/train.csv")
json.dump({"edges": [float(x) for x in tertile_edges(tr.rl.values)],
           "note": "tertiles of the 260k training MRL distribution; low/medium/high class boundaries"},
          open("weights/class_edges.json", "w"), indent=1)
print("ok   class_edges.json", json.load(open("weights/class_edges.json"))["edges"])
